const riskDescription=computed(()=>({蓝色:'较低',黄色:'一般',橙色:'较高',红色:'高'}[fireRisk.value]||'计算中'))
async function loadPublicData(){try{const [alertRes,parkRes]=await Promise.all([getLatestForestBroadcast(),getForestBootstrap()]);if(alertRes.code===200&&alertRes.data)currentAlert.value=alertRes.data;if(parkRes.code===200){visitorCount.value=parkRes.data?.parkInfo?.visitors||0;weather.value=parkRes.data?.weather||{};fireRisk.value=parkRes.data?.parkInfo?.fireRisk||'—';riskScore.value=parkRes.data?.riskAnalysis?.score??null;const zones=parkRes.data?.zones||[],incidents=parkRes.data?.incidents||[],evacuating=incidents.some(i=>i.status!=='closed'&&i.level==='三级');publicZones.value=zones.map(z=>{const incident=incidents.find(i=>i.status!=='closed'&&i.zone===z.name);return{...z,alertState:evacuating?'evacuate':incident?'incident':''}});zoneCount.value=zones.length;openZones.value=evacuating?0:zones.filter(v=>v.type==='游客活动区').length}}catch{currentAlert.value={level:'warning',title:'预警服务暂不可用',message:'暂时无法获取数据库中的最新提示，请听从现场广播和工作人员指引。',area:'—',exit:'游客中心服务台',time:'连接异常'}}}
